*{box-sizing:border-box}body{font-family:Inter,system-ui,sans-serif;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:680px;margin:42px auto;padding:0 18px}.panel{background:#fff;padding:28px;border-radius:18px;border:1px solid #e7ece8;box-shadow:0 12px 35px #173b2b0b}.eyebrow{font-size:11px;letter-spacing:1px;font-weight:850;color:#167c80}.property{font-size:22px;font-weight:850;margin:8px 0 22px}.rating-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:9px}.rating-option{position:relative}.rating-option input{position:absolute;opacity:0;pointer-events:none}.rating-option label{display:grid;place-items:center;min-height:54px;border:1px solid #dfe8e2;border-radius:11px;font-size:17px;font-weight:850;cursor:pointer;transition:.15s}.rating-option input:checked+label{background:#e8f5ee;border-color:#167c80;color:#126b70;box-shadow:0 0 0 2px #167c8018}.rating-option label:hover{border-color:#167c80}label.field-label{display:block;font-weight:800;margin:22px 0 8px}textarea{width:100%;min-height:150px;padding:13px;border:1px solid #dfe6e0;border-radius:11px;font:inherit;resize:vertical}button{margin-top:20px;background:#176b50;color:white;border:0;border-radius:10px;padding:14px 20px;font-weight:800;font-size:14px;cursor:pointer;width:100%}.hint{font-size:12px;color:#78857d;margin:9px 0 0}@media(max-width:480px){.rating-grid{grid-template-columns:repeat(5,1fr);gap:6px}.rating-option label{min-height:48px;font-size:15px}.panel{padding:20px}}
</style><?php require APP_ROOT . '/views/site/partials/account-theme.php'; ?></head><body><main class="wrap"><div class="eyebrow">GERÇEK KONAKLAMA DENEYİMİ</div><h1>Konaklamanızı değerlendirin</h1><section class="panel"><div class="property"><?= e($booking['title']) ?></div><form method="post" action="<?= e(app_url('/account/reviews')) ?>"><?= csrf_field() ?><input type="hidden" name="booking_id" value="<?= (int)$booking['id'] ?>"><label class="field-label">Genel puanınız (1–10)</label><div class="rating-grid"><?php for($score=1;$score<=10;$score++): ?><div class="rating-option"><input type="radio" id="rating<?= $score ?>" name="rating" value="<?= $score ?>" required ><label for="rating<?= $score ?>"><?= $score ?></label></div><?php endfor; ?></div><p class="hint">1: Çok kötü · 10: Mükemmel</p><label class="field-label" for="reviewBody">Deneyiminiz</label><textarea id="reviewBody" name="body" maxlength="3000" placeholder="Villa, temizlik, konum ve ev sahibi hakkındaki deneyiminizi paylaşın..."></textarea><button type="submit">Değerlendirmeyi gönder</button><p class="hint">Değerlendirmeniz yönetici onayından sonra yayınlanır.</p></form></section></main></body></html>